import json, os
def transform(g):
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    colors=sorted({x for r in g for x in r if x!=0})
    # rectangles: colors appearing as 4-sided border; detect via bbox fully containing cells
    out=[row[:] for row in g]
    rects=[]
    for c in colors:
        cells=[(r,i) for r,row in enumerate(g) for i,x in enumerate(row) if x==c]
        rs=[r for r,_ in cells]; cs=[i for _,i in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        # check border complete
        border=all(g[r][i]==c for r in range(r0,r1+1) for i in range(c0,c1+1) if r in(r0,r1) or i in(c0,c1))
        if border and r1>r0+1 and c1>c0+1: rects.append((r0,r1,c0,c1,c))
    # dot colors: nonzero colors not rectangle colors
    rectcols={c for *_,c in rects}
    dots=sorted([c for c in colors if c not in rectcols])
    # map by count match to checker capacity
    def cap(r):
        r0,r1,c0,c1,_=r
        return sum(1 for rr in range(r0+1,r1) for cc in range(c0+1,c1) if (rr+cc)%2==0)
    caps={cap(r):r for r in rects}
    for d in dots:
        r=caps[cnt[d]]
        r0,r1,c0,c1,_=r
        for rr in range(r0+1,r1):
            for cc in range(c0+1,c1):
                if (rr+cc)%2==0: out[rr][cc]=d
    # remove dots
    for r in range(len(out)):
        for i in range(len(out[0])):
            if out[r][i] in dots: out[r][i]=0
    return out

